const ago=iso=>{const m=Math.round((Date.now()-Date.parse(iso))/6e4);if(!iso||!Number.isFinite(m))return'never';if(m<60)return m+'m ago';if(m<1440)return Math.round(m/60)+'h ago';return Math.round(m/1440)+'d ago'};
