  const gsc=gscAll.slice(-days),gscPrev=gscAll.slice(-days*2,-days),ga4=ga4All.slice(-days),ga4Prev=ga4All.slice(-days*2,-days),sum=(rows,k)=>rows.reduce((n,r)=>n+Number(r.data[k]||0),0);
