async function loadActivity(cid){const el=$('#activity-stream');if(!el)return;const label={create_audits:'Audit recorded',test_integration:'Connection tested',save_integration:'API settings saved',replace_wordpress_secret:'WordPress password saved',update_client:'Workspace settings updated',create_client:'Workspace created',connect_google_oauth:'Google account connected',configure_member:'Team member updated'};const detail=d=>{try{const o=JSON.parse(d);return o.title||o.provider||o.email||(o.to?'Status: '+String(o.to).replaceAll('_',' '):'')}catch{return String(d||'')}};try{const all=await api('activity?client_id='+cid);if(!$('#activity-stream'))return;const syncs=all.filter(a=>/traffic/.test(a.action)),items=all.filter(a=>!/traffic|sync_keyword|create_keywords|keyword_volume/.test(a.action));if(syncs.length)items.push({action:'google_sync',actor:syncs[0].actor,created_at:syncs[0].created_at,detail:''});items.sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));const ic=a=>/sync/.test(a)?'sync':/approve|verify/.test(a)?'task_alt':/reject|fail/.test(a)?'error':/audit/.test(a)?'radar':/connect|integration|secret/.test(a)?'link':/create|save|update/.test(a)?'edit_note':'history';el.innerHTML=items.length?items.slice(0,5).map(a=>{const text=a.action==='google_sync'?'Search Console & GA4 data synced':label[a.action]||String(a.action).replaceAll('_',' ').replace(/^./,m=>m.toUpperCase()),extra=a.action==='google_sync'?'':detail(a.detail);return`<div class="act"><span class="material-symbols-outlined">${ic(a.action)}</span><div><div class="act-top"><b>${esc(text)}</b><span>${esc(ago(a.created_at))}</span></div><p>${esc(String(a.actor||'System'))}${extra?' · '+esc(String(extra).slice(0,90)):''}</p></div></div>`}).join(''):'<p class="sub">No activity recorded for this client yet.</p>'}catch(e){el.innerHTML=`<p class="sub">${esc(e.message)}</p>`}}

