const CS_STAGES=[['idea','Idea','Planned topics'],['brief','Brief','Brief written'],['outline','Outline','Being structured'],['draft','Draft','Being written'],['review','Review & fact-check','Waiting for approval'],['approved','Approved','Ready to send'],['wp','WordPress draft','Sent to WordPress']];
const csStage=r=>{const d=r.data,s=r.status;if(['pushing','pushed','push_failed'].includes(s))return'wp';if(s==='approved')return'approved';if(s==='in_review')return'review';if(String(d.body||'').trim())return'draft';if(String(d.outline||'').trim())return'outline';if(String(d.brief||'').trim()&&s!=='planned')return'brief';return'idea'};
const csAge=r=>{const stamp=Date.parse(r.updated_at||r.created_at||'');if(!Number.isFinite(stamp))return'Other';const days=(Date.now()-stamp)/864e5;return days<=7?'New':days>=30?'Old':'Other'};
