const CS_CATEGORIES=[['draft','Draft','Being written'],['wp','WordPress draft','Sent to WordPress'],['new','New','Updated within 7 days'],['old','Old','Updated 30+ days ago'],['other','Other','Updated 8–29 days ago']];
const csCategoryMatches=(r,key)=>key==='draft'?csStage(r)==='draft':key==='wp'?csStage(r)==='wp':csAge(r)===({new:'New',old:'Old',other:'Other'}[key]||'');
const CS_MANUAL={brand_verified:'Brand voice and disclaimer reviewed',facts_verified:'Facts verified',links_verified:'Link targets verified',originality_verified:'Originality / existing-page duplication checked',schema_verified:'FAQ, image alt text and schema reviewed'};
function mdToHtml(md,ownHost){const inline=t=>esc(t).replace(/!\[([^\]]*)\]\((https:\/\/[^)\s]+)\)/g,(m,alt,u)=>`<figure class="art-img"><img src="${mediaProxyUrl(u)}" data-src="${esc(u)}" alt="${alt||'Article image'}" loading="lazy"><figcaption>${alt||'Article image'}</figcaption></figure>`).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(m,t,u)=>{let own=false;try{own=new URL(u.replace(/&amp;/g,'&')).hostname.replace(/^www\./,'')===ownHost}catch{}const long=own&&t.length>55;return`<a class="${own?'int-link':'ext-link'}${long?' long-link':''}" href="${u}" target="_blank" rel="noopener"${long?` title="${t}" aria-label="${t}"`:''}>${t}</a>`}).replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/(^|\s)\*([^*]+)\*/g,'$1<i>$2</i>');
 const out=[];let list=null;for(const raw of String(md||'').split('\n')){const l=raw.trimEnd(),check=l.match(/\[CHECK:([^\]]*)\]/i);if(list&&!/^\s*([-*]|\d+\.)\s+/.test(l)){out.push(`</${list}>`);list=null}
  if(check){out.push(`<div class="claim-blocked"><div class="row"><span class="tag bad">${icon('gpp_maybe')} Claim blocked by gatekeeper</span><span class="mono-sub">Citation missing</span></div><p>${inline(l.replace(/\[CHECK:[^\]]*\]/ig,'').trim()||'Unverified statement')}</p><p class="mono-sub">To verify: ${esc(check[1].trim()||'add a trusted source')}</p></div>`);continue}
  let m;if((m=l.match(/^(#{1,4})\s+(.*)$/))){const n=m[1].length;out.push(`<h${n+1} class="art-h${n}">${inline(m[2])}${n>1?`<span class="mono-sub">H${n}</span>`:''}</h${n+1}>`)}else if((m=l.match(/^\s*([-*]|\d+\.)\s+(.*)$/))){const t=/\d/.test(m[1])?'ol':'ul';if(!list){list=t;out.push(`<${t}>`)}out.push(`<li>${inline(m[2])}</li>`)}else if(/^>\s?/.test(l))out.push(`<blockquote>${inline(l.replace(/^>\s?/,''))}</blockquote>`);else if(l.trim())out.push(`<p>${inline(l)}</p>`)}if(list)out.push(`</${list}>`);return out.join('')}
function contentKindLabel(d){return d?.landing?'Landing page':d?.blog?'Blog':'Article'}
function imageFits(url,keyword){const raw=String(url||'');if(/seo-studio-/i.test(raw))return true;let hay=raw;try{hay=decodeURIComponent(raw)}catch{}hay=hay.toLowerCase();const stop=new Set(['the','and','for','with','from','your','best','top','how','what','why','when','where','this','that','into','over','near']);const focus=String(keyword||'').toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>2&&!stop.has(w));if(!focus.length)return true;const hits=focus.filter(w=>hay.includes(w));return hits.length>=Math.min(2,focus.length)&&hits.length>=Math.ceil(focus.length/2)}
function fittingBody(md,keyword){return String(md||'').replace(/!\[([^\]]*)\]\((https:\/\/[^)\s]+)\)/g,(m,alt,u)=>imageFits(u,keyword)?m:'')}
