function readability(text){const words=(text.match(/[A-Za-z]+/g)||[]),sentences=Math.max(1,(text.match(/[.!?]+(\s|$)/g)||[]).length),syl=words.reduce((n,w)=>n+Math.max(1,(w.toLowerCase().replace(/e$/,'').match(/[aeiouy]+/g)||[]).length),0);if(words.length<30)return null;const ease=206.835-1.015*(words.length/sentences)-84.6*(syl/words.length),grade=0.39*(words.length/sentences)+11.8*(syl/words.length)-15.59;return{ease:Math.round(ease),grade:Math.max(1,Math.round(grade)),label:ease>=70?'Easy':ease>=50?'Fairly easy':ease>=30?'Difficult':'Very difficult'}}
function inlineToMarkdown(root){if(!root)return'';const textOf=node=>{let s='';node.childNodes.forEach(n=>{if(n.nodeType===3)s+=n.textContent;else if(n.nodeType!==1||n.classList?.contains('mono-sub')||n.tagName==='FIGCAPTION')return;else if(n.tagName==='BR')s+='\n';else if(n.tagName==='B'||n.tagName==='STRONG')s+='**'+textOf(n)+'**';else if(n.tagName==='I'||n.tagName==='EM')s+='*'+textOf(n)+'*';else if(n.tagName==='A')s+='['+textOf(n).trim()+']('+(n.getAttribute('href')||'')+')';else if(n.tagName==='IMG'&&n.dataset.src)s+='!['+(n.getAttribute('alt')||'')+']('+n.dataset.src+')';else if(n.tagName==='BUTTON')return;else s+=textOf(n)});return s.replace(/\u00a0/g,' ')};const lines=[];const walk=el=>{el.childNodes.forEach(n=>{if(n.nodeType!==1||n.classList.contains('mono-sub'))return;const tag=n.tagName,cls=[...n.classList].find(c=>/^art-h\d$/.test(c));if(cls)lines.push('#'.repeat(Number(cls.slice(5)))+' '+textOf(n).replace(/\s+/g,' ').trim());else if(tag==='P'||tag==='BLOCKQUOTE'){const t=textOf(n).replace(/\s+/g,' ').trim();if(t)lines.push((tag==='BLOCKQUOTE'?'> ':'')+t)}else if(tag==='UL'||tag==='OL')[...n.children].forEach((li,i)=>{const t=textOf(li).replace(/\s+/g,' ').trim();if(t)lines.push((tag==='OL'?(i+1)+'. ':'- ')+t)});else if(tag==='FIGURE'){const img=n.querySelector('img');if(img?.dataset.src)lines.push('!['+(img.getAttribute('alt')||'')+']('+img.dataset.src+')')}else if(n.querySelector('p,h2,h3,h4,h5,ul,ol,blockquote,figure'))walk(n);else{const t=textOf(n).replace(/\s+/g,' ').trim();if(t)lines.push(t)}})};walk(root);return lines.join('\n\n')}
