async function saveArticle(el){const root=document.getElementById('article-edit');if(!root)return;const r=state.records.find(x=>x.id===root.dataset.id);if(!r)return toast('Record not found. Reload the workspace.');const titleEl=root.closest('.content-preview')?.querySelector('.serp-title'),heading=titleEl?titleEl.textContent.replace(/\s+/g,' ').trim():'',was=r.status;const imgs=[...root.querySelectorAll('img[data-src]')],data={...r.data,body:inlineToMarkdown(root),meta_title:heading||r.data.meta_title||r.title};if(imgs.length){data.blog_images=imgs.map(i=>i.dataset.src).join('\n');const kept=String(r.data.content_media||'').split(/\r?\n/).filter(line=>imgs.some(i=>line.includes(i.dataset.src)));const added=imgs.filter(i=>i.dataset.mediaId&&!kept.some(line=>line.includes(i.dataset.src))).map(i=>i.dataset.mediaId+' '+i.dataset.src);data.content_media=[...kept,...added].filter(Boolean).join('\n')}el.disabled=true;try{await api('records/'+r.id,'PUT',{client_id:state.client.id,kind:'content',title:r.title,data,revision:r.revision});state.articleEdit='';await reload();toast(['in_review','approved'].includes(was)?'Article saved. It is back in draft for another check.':'Article saved.')}catch(e){error(e)}finally{if(el.isConnected)el.disabled=false}}
