async function kbLink(){const c=state.client;modal('Link a Knowledgebase brand','<p>Loading brands…</p>');let d;try{d=await api('kb/brands')}catch(e){return error(e)}modal('Link a Knowledgebase brand',`<p>Choose which Brandroom brand belongs to <b>${esc(c.name)}</b>. AI drafts and AI fixes for this client will use that brand’s knowledge.</p><form id="kb-link"><select name="slug"><option value="">Match automatically by website</option>${d.brands.map(b=>`<option value="${esc(b.slug)}" ${c.data.kb_client_id===b.slug?'selected':''}>${esc(b.name)}${b.website?' · '+esc(b.website):''}</option>`).join('')}</select><div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">Save link</button></div></form>`);$('#kb-link').onsubmit=async e=>{e.preventDefault();try{await api('clients/'+c.id,'PUT',{name:c.name,url:c.url,platform:c.platform,data:{...c.data,kb_client_id:e.target.elements.slug.value},revision:c.revision});dialog.close();await reload(c.id);state.kbBrand=null;render();toast('Brand link saved.')}catch(err){error(err)}}}
