function clientSwitcher(){if(!state.boot)return profile();const P=state.boot.portfolio?.clients||[],info=id=>P.find(x=>x.id===id)||{},recent=recentClients();
 const list=state.boot.clients.slice().sort((a,b)=>{const ra=recent.indexOf(a.id),rb=recent.indexOf(b.id);return(ra<0?99:ra)-(rb<0?99:rb)||a.name.localeCompare(b.name)});
 const keep=['all-clients','settings','admin','not-found'].includes(route)?'client-dashboard':route;
 const row=c=>{const x=info(c.id),h=x.health?.score,n=Number(x.approvals||x.in_review||0);return`<button type="button" class="sw-row ${c.id===state.client?.id?'current':''}" data-action="sw-pick" data-id="${c.id}" data-q="${esc((c.name+' '+c.url).toLowerCase())}"><span class="sw-avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><span class="sw-main"><b>${esc(c.name)}</b><small>${esc(host(c.url))}${recent.includes(c.id)?' · recently used':''}</small></span><span class="pill ${h===undefined?'':h>=90?'good':h>=70?'warn':'bad'}" title="Site health">${h===undefined?'—':num(Math.round(h))+'%'}</span><span class="sw-pending ${n?'on':''}" title="Approvals waiting">${n?n+' waiting':'0 waiting'}</span></button>`};
 modal('Switch client',`<div class="sw"><label class="sw-search">${icon('search')}<input id="sw-q" type="search" placeholder="Search clients by name or website" autocomplete="off" aria-label="Search clients"></label><div class="sw-list" id="sw-list" role="listbox" aria-label="Clients">${list.map(row).join('')}</div><p class="sw-empty sub" hidden>No client matches.</p><p class="sub sw-hint">Opens the same page (${esc(routeNames[keep]||'Dashboard')}) for the client you pick. Shortcut: <kbd>${isMac?'⌘':'Ctrl'}</kbd>+<kbd>Shift</kbd>+<kbd>K</kbd> · ↑↓ to move · Enter to open</p></div><div class="dialog-actions">${admin()?btn(icon('add')+'Create client','new-client'):''}</div>`);
 const q=$('#sw-q'),rows=()=>[...document.querySelectorAll('#sw-list .sw-row:not([hidden])')];
 q.oninput=()=>{const t=q.value.trim().toLowerCase();let any=false;for(const r of document.querySelectorAll('#sw-list .sw-row')){r.hidden=!!t&&!r.dataset.q.includes(t);any=any||!r.hidden}$('.sw-empty').hidden=any;rows()[0]?.classList.add('kb');rows().slice(1).forEach(r=>r.classList.remove('kb'))};
 q.onkeydown=e=>{const rs=rows();let i=rs.findIndex(r=>r.classList.contains('kb'));if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();rs[i]?.classList.remove('kb');i=e.key==='ArrowDown'?Math.min(rs.length-1,i+1):Math.max(0,i-1);rs[i]?.classList.add('kb');rs[i]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'){e.preventDefault();(rs[i]||rs[0])?.click()}};
 setTimeout(()=>q.focus(),30)}
