// Plain-language labels with an (i) tooltip for SEO jargon. Runs after each render on UI labels only
// (headings, tabs, table headers, KPI labels), never on client data such as keywords or page titles.
const GLOSSARY=[
 [/almost page 1/i,'Almost page 1','Keywords ranking in positions 4–20. A small push can move them onto page 1, where most clicks happen.'],
 [/cannibali[sz]ation/i,'Competing pages','Two or more of your pages compete for the same search, so Google splits the ranking between them.'],
 [/\bAEO\b/,'AI search','How often AI assistants (ChatGPT, Gemini, Perplexity) mention the brand and link to the website when people ask important questions.'],
 [/issue lifecycle/i,'Issue changes','New, worse, improved and fixed issues compared with the previous audit.'],
 [/frozen/i,null,'Numbers are saved when the report is created and do not change afterwards, so the client sees exactly what was approved.'],
 [/safe mode/i,null,'Nothing changes on a client website without approval. Content is sent to WordPress only as a draft.'],
 [/\bCTR\b|click-through rate/i,null,'Clicks divided by impressions: how often people who see the result in Google click it.'],
 [/^impressions$/i,null,'How many times the website appeared in Google results.'],
 [/avg position|average position/i,null,'Average Google ranking. Lower is better: 1 is the top result.'],
 [/\bLCP\b/,null,'Largest Contentful Paint: how fast the main content appears. Good is under 2.5 seconds.'],
 [/\bCLS\b/,null,'Cumulative Layout Shift: how much the page jumps while loading. Good is under 0.1.'],
 [/core web vitals/i,null,"Google's page-experience scores: loading speed (LCP) and visual stability (CLS)."],
 [/search intent|^intent$/i,null,'What the searcher wants: information, comparing options, buying, or finding a specific site.'],
 [/\bcitations?\b/i,null,'An AI answer linking to the client website as a source.'],
 [/health score|site health/i,null,'Latest full-crawl score, minus points for open issues (critical −10, high −5, medium −2, low −0.5).'],
 [/schema|json-ld/i,null,'Structured data that tells Google and AI what a page is about (business, FAQ, article, product...).'],
 [/keyword difficulty|^kd$/i,null,'How hard it is to rank in the top 10 for this keyword (0 = easy, 100 = very hard).']];
const TIP_TARGETS='main .kpi-head>span:first-child,main .tabs button,main th,main h2,main h3.mini-title,main .stat-label,main .chip-label,main .deficits span,main .ph-hero span,main .audit-kpis .kpi-head span,header [data-safe-badge]';
function addTips(root=document){for(const el of root.querySelectorAll(TIP_TARGETS)){if(el.dataset.tipped)continue;el.dataset.tipped='1';
 for(const node of [...el.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim())){const text=node.textContent;const g=GLOSSARY.find(([re])=>re.test(text.trim()));if(!g)continue;const [re,plain,help]=g;if(plain)node.textContent=text.replace(re,plain);
  const t=document.createElement('span');t.className='tip';t.tabIndex=0;t.setAttribute('role','button');t.setAttribute('aria-label','What does this mean? '+help);t.dataset.tip=help;t.textContent='i';node.after(t);break}}}
function wireTips(){let box=$('#tipbox');if(!box){box=document.createElement('div');box.id='tipbox';box.setAttribute('role','tooltip');box.hidden=true;document.body.append(box)}
 const show=t=>{box.textContent=t.dataset.tip;box.hidden=false;const r=t.getBoundingClientRect(),w=Math.min(280,innerWidth-24);box.style.width=w+'px';let x=Math.min(Math.max(12,r.left+r.width/2-w/2),innerWidth-w-12),y=r.top-box.offsetHeight-8;if(y<8)y=r.bottom+8;box.style.left=x+'px';box.style.top=y+'px'},hide=()=>{box.hidden=true};
 document.addEventListener('mouseover',e=>{const t=e.target.closest('.tip');if(t)show(t)});document.addEventListener('mouseout',e=>{if(e.target.closest('.tip'))hide()});
 document.addEventListener('focusin',e=>{const t=e.target.closest?.('.tip');if(t)show(t)});document.addEventListener('focusout',e=>{if(e.target.closest?.('.tip'))hide()});
 // Tapping the (i) explains it instead of triggering the tab or button around it.
 document.addEventListener('click',e=>{const t=e.target.closest('.tip');if(!t)return;e.preventDefault();e.stopPropagation();if(document.activeElement===t&&!box.hidden){t.blur();hide()}else{t.focus();show(t)}},true);
 addEventListener('scroll',hide,{passive:true})}
