const shiftMonth=(m,n)=>{const [y,mo]=m.split('-').map(Number),d=new Date(Date.UTC(y,mo-1+n,1));return d.toISOString().slice(0,7)};
function monthWeeks(m){const [y,mo]=m.split('-').map(Number),last=new Date(Date.UTC(y,mo,0)).getUTCDate(),weeks=[];let start=1;while(start<=last){const d=new Date(Date.UTC(y,mo-1,start)),dow=(d.getUTCDay()+6)%7,end=Math.min(last,start+6-dow);weeks.push([`${m}-${String(start).padStart(2,'0')}`,`${m}-${String(end).padStart(2,'0')}`]);start=end+1}return weeks}
