  const plan=state.records.find(r=>r.kind==='plans'&&r.data.month===m),target=Number(plan?.data.target||c.data.monthly_target||0),done=inMonth.filter(r=>['approved','pushing','pushed'].includes(r.status)).length;
  const kwOf=r=>state.records.find(k=>k.kind==='keywords'&&r.data.keyword&&k.title.toLowerCase()===String(r.data.keyword).toLowerCase()),demand=inMonth.reduce((n,r)=>n+Number(kwOf(r)?.data.volume||0),0),impr=inMonth.reduce((n,r)=>n+Number(kwOf(r)?.data.impressions||0),0);
