  const pages=Object.entries(routeNames).filter(([k,v])=>k!=='not-found'&&v.toLowerCase().includes(t)).slice(0,5),clients=(state.boot?.clients||[]).filter(c=>(c.name+' '+c.url).toLowerCase().includes(t)).slice(0,6);
