// In-app navigation: switch sections without reloading the page, so data stays loaded and nothing flashes.
const ROUTES=['client-dashboard','all-clients','client-setup','keyword-research','site-audit','fixes-and-approvals','developer-tickets','content-studio','aeo-visibility','schema-generator','monthly-plan','reports-admin','admin','settings','not-found'];
function swapRouteCss(r){const src=r==='admin'||r==='settings'?'reports-admin':r==='not-found'?'client-dashboard':r,cur=[...document.querySelectorAll('link[rel=stylesheet]')].find(l=>/^\/[a-z-]+\.css$/.test(l.getAttribute('href')||'')&&l.getAttribute('href')!=='/app.css');if(!cur||cur.getAttribute('href')==='/'+src+'.css')return Promise.resolve();return new Promise(res=>{const l=document.createElement('link');l.rel='stylesheet';l.href='/'+src+'.css';l.onload=()=>{cur.remove();res()};l.onerror=()=>{l.remove();res()};cur.after(l);setTimeout(res,1500)})}
async function goTo(r,cid,tab='',push=true){const clientChanged=cid&&cid!==state.client?.id;if(!ROUTES.includes(r)||!state.boot){const q=new URLSearchParams();if(cid)q.set('client',cid);if(tab)q.set('tab',tab);return location.assign('/'+r+'/'+(q.size?'?'+q:''))}
 const q=new URLSearchParams();if(cid||state.client)q.set('client',cid||state.client.id);if(tab)q.set('tab',tab);const url='/'+r+'/'+(q.size?'?'+q:'');
 if(push)history.pushState({r,tab},'',url);if(dialog?.open)dialog.close();setNavOpen(false);
 const main=$('main');main.classList.add('swapping');await swapRouteCss(r);
 route=r;document.body.dataset.route=r;state.tab=tab;state.query='';state.filters={};state.kwPage=0;document.title='Climb · '+(routeNames[r]||r).toLowerCase();
 const paint=async()=>{if(clientChanged)await reload(cid);else render();scrollTo({top:0})};
 try{if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)await document.startViewTransition(paint).updateCallbackDone;else await paint()}catch(e){error(e)}finally{main.classList.remove('swapping')}}
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download')||a.dataset.action)return;let u;try{u=new URL(a.href,location.href)}catch{return}if(u.origin!==location.origin)return;const m=u.pathname.match(/^\/([a-z-]+)\/?$/);if(!m||!ROUTES.includes(m[1]))return;e.preventDefault();goTo(m[1],u.searchParams.get('client')||state.client?.id,u.searchParams.get('tab')||'')});
addEventListener('popstate',()=>{const m=location.pathname.match(/^\/([a-z-]+)\/?$/),p=new URLSearchParams(location.search);if(m&&ROUTES.includes(m[1]))goTo(m[1],p.get('client')||state.client?.id,p.get('tab')||'',false);else location.reload()});
