 const issues=n('issues',r=>r.status==='open'&&['critical','high'].includes(r.data.severity)),approvalKinds=['fixes','content','schemas','reports'],waiting=(state.boot?.counts||[]).filter(x=>x.status==='in_review'&&approvalKinds.includes(x.kind)&&(!c||x.client_id===c.id)).reduce((a,x)=>a+Number(x.n),0),tickets=n('tickets',r=>r.status==='open'),review=n('content',r=>r.status==='in_review'),decline=(state.insights?.pages_down||[]).length;
 const navSec={'keyword-research':'keywords','site-audit':'audit','fixes-and-approvals':'fixes','developer-tickets':'tickets','content-studio':'content','monthly-plan':'content','aeo-visibility':'aeo','schema-generator':'schema','reports-admin':'reports'},acc=state.boot?.user?.access?.sections||{};const item=(path,label,ic,badge='',cls='')=>acc[navSec[path]]==='none'?'':`<a data-path="${path}" href="/${path}/"><span class="material-symbols-outlined">${ic}</span><span class="nav-label">${label}</span>${badge?`<span class="nav-badge ${cls}">${badge}</span>`:''}</a>`;
